 *
 * A2-2 CP/AP RPTUN transport. RPMsg data stays in shared SRAM and BK7258
 * Mailbox v2 provides the hardware doorbell in both directions.
 ****************************************************************************/

#include <nuttx/config.h>

#ifdef CONFIG_RPTUN

#include <assert.h>
#include <errno.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>
